func (s Node) JSONSize() int {
	size := 563
	size += ((len(s.Blob) + 2) / 3) * 4
	if n := len(s.Children); n > 0 {
		size += n - 1
	}
	for i0 := range s.Children {
		size += s.Children[i0].JSONSize()
	}
	if n := len(s.Coords); n > 0 {
		size += n - 1
	}
	size += len(s.Coords) * 25
	if n := len(s.Matrix); n > 0 {
		size += n - 1
	}
	for i0 := range s.Matrix {
		size += 4
		if n := len(s.Matrix[i0]); n > 0 {
			size += n - 1
		}
		size += len(s.Matrix[i0]) * 20
	}
	size += len(s.Name) * 2
	if s.Parent != nil {
		size += 10
		size += (*s.Parent).JSONSize()
	}
	size += len(s.Props) * 4
	for k, v := range s.Props {
		size += len(k) * 2
		size += len(v)*2 + 2
	}
	if n := len(s.Raw); n > 0 {
		size += n
	} else {
		size += 4
	}
	if n := len(s.Refs); n > 0 {
		size += n - 1
	}
	for i0 := range s.Refs {
		if s.Refs[i0] == nil {
			size += 4
		} else {
			size += (*s.Refs[i0]).JSONSize()
		}
	}
	if n := len(s.Tags); n > 0 {
		size += n - 1
	}
	for i0 := range s.Tags {
		size += len(s.Tags[i0])*2 + 2
	}
	return size
}

