func (recv Claim) DecodeFromStream(s *scan.Stream) (result Claim, _ error) {
	result = recv
	seenAud := false
	seenExp := false
	seenIat := false
	seenIss := false
	seenJti := false
	seenNbf := false
	seenSub := false
	err := s.ObjectOpen()
	if err != nil {
		return result, decode.NewParseErr("", s.Pos, err)
	}
	err = s.SkipSpace()
	if err != nil {
		return result, decode.NewParseErr("", s.Pos, err)
	}
	if s.Pos >= len(s.Bytes()) {
		if err = s.ReadMore(s.Pos); err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		s.Pos = 0
	}
	if s.Bytes()[s.Pos] == '}' {
		s.Pos++
		if !seenIss {
			return result, &validation.RequiredError{Path: []string{"iss"}}
		}
		if !seenSub {
			return result, &validation.RequiredError{Path: []string{"sub"}}
		}
		return result, nil
	}
	for {
		var key string
		key, err = s.KeyView()
		if err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		switch key {
		case "aud":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("aud", s.Pos, err)
			}
			if seenAud {
				return result, &validation.DuplicateKeyError{Path: []string{"aud"}}
			}
			seenAud = true
			result.Aud, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("aud", s.Pos, err)
			}
		case "exp":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("exp", s.Pos, err)
			}
			if seenExp {
				return result, &validation.DuplicateKeyError{Path: []string{"exp"}}
			}
			seenExp = true
			result.Exp, err = s.Int64()
			if err != nil {
				return result, decode.NewParseErr("exp", s.Pos, err)
			}
			if result.Exp < 0 {
				return result, &validation.GTEError{Path: []string{"exp"}, Limit: 0, Value: result.Exp}
			}
		case "iat":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("iat", s.Pos, err)
			}
			if seenIat {
				return result, &validation.DuplicateKeyError{Path: []string{"iat"}}
			}
			seenIat = true
			result.Iat, err = s.Int64()
			if err != nil {
				return result, decode.NewParseErr("iat", s.Pos, err)
			}
			if result.Iat < 0 {
				return result, &validation.GTEError{Path: []string{"iat"}, Limit: 0, Value: result.Iat}
			}
		case "iss":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("iss", s.Pos, err)
			}
			if seenIss {
				return result, &validation.DuplicateKeyError{Path: []string{"iss"}}
			}
			seenIss = true
			result.Iss, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("iss", s.Pos, err)
			}
		case "jti":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("jti", s.Pos, err)
			}
			if seenJti {
				return result, &validation.DuplicateKeyError{Path: []string{"jti"}}
			}
			seenJti = true
			result.Jti, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("jti", s.Pos, err)
			}
		case "nbf":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("nbf", s.Pos, err)
			}
			if seenNbf {
				return result, &validation.DuplicateKeyError{Path: []string{"nbf"}}
			}
			seenNbf = true
			result.Nbf, err = s.Int64()
			if err != nil {
				return result, decode.NewParseErr("nbf", s.Pos, err)
			}
		case "sub":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("sub", s.Pos, err)
			}
			if seenSub {
				return result, &validation.DuplicateKeyError{Path: []string{"sub"}}
			}
			seenSub = true
			result.Sub, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("sub", s.Pos, err)
			}
		default:
			return result, &validation.UnknownKeyError{Path: []string{strings.Clone(key)}}
		}

		err = s.SkipSpace()
		if err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		if s.Pos >= len(s.Bytes()) {
			if err = s.ReadMore(s.Pos); err != nil {
				return result, decode.NewParseErr("", s.Pos, err)
			}
			s.Pos = 0
		}
		c := s.Bytes()[s.Pos]
		if c == ',' {
			s.Pos++
			err = s.SkipSpace()
			if err != nil {
				return result, decode.NewParseErr("", s.Pos, err)
			}
			continue
		}
		if c == '}' {
			s.Pos++
			if !seenIss {
				return result, &validation.RequiredError{Path: []string{"iss"}}
			}
			if !seenSub {
				return result, &validation.RequiredError{Path: []string{"sub"}}
			}
			return result, nil
		}
		return result, decode.NewParseErr("", s.Pos, scan.ErrBadObject)
	}
}

func (s Claim) JSONSize() int {
	size := 109
	if s.Aud != "" {
		size += 9
		size += len(s.Aud) * 2
	}
	size += len(s.Iss) * 2
	size += len(s.Jti) * 2
	size += len(s.Sub) * 2
	return size
}

func (s Claim) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, '{')
	start := len(dst)
	if s.Aud != "" {
		if len(dst) > start {
			dst = append(dst, ',')
		}
		dst = append(dst, "\"aud\":\""...)
		dst = encode.AppendStringNoHTML(dst, s.Aud)
	}
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"exp\":"...)
	dst = strconv.AppendInt(dst, s.Exp, 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"iat\":"...)
	dst = strconv.AppendInt(dst, s.Iat, 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"iss\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Iss)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"jti\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Jti)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"nbf\":"...)
	dst = strconv.AppendInt(dst, s.Nbf, 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"sub\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Sub)
	return append(dst, '}'), nil
}

