func (recv NoValidationHeavy) DecodeFromStream(s *scan.Stream) (result NoValidationHeavy, _ error) {
	result = recv
	seenAge := false
	seenCountry := false
	seenEmail := false
	seenLang := false
	seenName := false
	seenPhone := false
	seenRole := false
	seenScore := false
	seenURL := false
	seenUsername := false
	err := s.ObjectOpen()
	if err != nil {
		return result, decode.NewParseErr("", s.Pos, err)
	}
	err = s.SkipSpace()
	if err != nil {
		return result, decode.NewParseErr("", s.Pos, err)
	}
	if s.Pos >= len(s.Bytes()) {
		if err = s.ReadMore(s.Pos); err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		s.Pos = 0
	}
	if s.Bytes()[s.Pos] == '}' {
		s.Pos++
		return result, nil
	}
	for {
		var key string
		key, err = s.KeyView()
		if err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		switch key {
		case "age":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("age", s.Pos, err)
			}
			if seenAge {
				return result, &validation.DuplicateKeyError{Path: []string{"age"}}
			}
			seenAge = true
			var iv int64
			iv, err = s.Int64()
			if err != nil {
				return result, decode.NewParseErr("age", s.Pos, err)
			}
			result.Age = int(iv)
		case "country":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("country", s.Pos, err)
			}
			if seenCountry {
				return result, &validation.DuplicateKeyError{Path: []string{"country"}}
			}
			seenCountry = true
			result.Country, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("country", s.Pos, err)
			}
		case "email":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("email", s.Pos, err)
			}
			if seenEmail {
				return result, &validation.DuplicateKeyError{Path: []string{"email"}}
			}
			seenEmail = true
			result.Email, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("email", s.Pos, err)
			}
		case "lang":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("lang", s.Pos, err)
			}
			if seenLang {
				return result, &validation.DuplicateKeyError{Path: []string{"lang"}}
			}
			seenLang = true
			result.Lang, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("lang", s.Pos, err)
			}
		case "name":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("name", s.Pos, err)
			}
			if seenName {
				return result, &validation.DuplicateKeyError{Path: []string{"name"}}
			}
			seenName = true
			result.Name, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("name", s.Pos, err)
			}
		case "phone":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("phone", s.Pos, err)
			}
			if seenPhone {
				return result, &validation.DuplicateKeyError{Path: []string{"phone"}}
			}
			seenPhone = true
			result.Phone, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("phone", s.Pos, err)
			}
		case "role":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("role", s.Pos, err)
			}
			if seenRole {
				return result, &validation.DuplicateKeyError{Path: []string{"role"}}
			}
			seenRole = true
			result.Role, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("role", s.Pos, err)
			}
		case "score":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("score", s.Pos, err)
			}
			if seenScore {
				return result, &validation.DuplicateKeyError{Path: []string{"score"}}
			}
			seenScore = true
			result.Score, err = s.Float64()
			if err != nil {
				return result, decode.NewParseErr("score", s.Pos, err)
			}
		case "url":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("url", s.Pos, err)
			}
			if seenURL {
				return result, &validation.DuplicateKeyError{Path: []string{"url"}}
			}
			seenURL = true
			result.URL, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("url", s.Pos, err)
			}
		case "username":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("username", s.Pos, err)
			}
			if seenUsername {
				return result, &validation.DuplicateKeyError{Path: []string{"username"}}
			}
			seenUsername = true
			result.Username, err = s.String()
			if err != nil {
				return result, decode.NewParseErr("username", s.Pos, err)
			}
		default:
			return result, &validation.UnknownKeyError{Path: []string{strings.Clone(key)}}
		}

		err = s.SkipSpace()
		if err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		if s.Pos >= len(s.Bytes()) {
			if err = s.ReadMore(s.Pos); err != nil {
				return result, decode.NewParseErr("", s.Pos, err)
			}
			s.Pos = 0
		}
		c := s.Bytes()[s.Pos]
		if c == ',' {
			s.Pos++
			err = s.SkipSpace()
			if err != nil {
				return result, decode.NewParseErr("", s.Pos, err)
			}
			continue
		}
		if c == '}' {
			s.Pos++
			return result, nil
		}
		return result, decode.NewParseErr("", s.Pos, scan.ErrBadObject)
	}
}

func (s NoValidationHeavy) JSONSize() int {
	size := 150
	size += len(s.Country) * 2
	size += len(s.Email) * 2
	size += len(s.Lang) * 2
	size += len(s.Name) * 2
	size += len(s.Phone) * 2
	size += len(s.Role) * 2
	size += len(s.URL) * 2
	size += len(s.Username) * 2
	return size
}

func (s NoValidationHeavy) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"age\":"...)
	dst = strconv.AppendInt(dst, int64(s.Age), 10)
	dst = append(dst, ",\"country\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Country)
	dst = append(dst, ",\"email\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Email)
	dst = append(dst, ",\"lang\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Lang)
	dst = append(dst, ",\"name\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Name)
	dst = append(dst, ",\"phone\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Phone)
	dst = append(dst, ",\"role\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Role)
	dst = append(dst, ",\"score\":"...)
	if dst, err = encode.AppendFloat(dst, s.Score, 64); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"url\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.URL)
	dst = append(dst, ",\"username\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Username)
	return append(dst, '}'), nil
}

